// 本文件定义 / 命令同步补全和 @ 文件异步补全 TUI 组件。
package bubble

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"unicode"
	"unicode/utf8"

	tea "github.com/charmbracelet/bubbletea"
)

// completionKind 区分命令补全和文件补全。
type completionKind int

const (
	completionKindCommand completionKind = iota
	completionKindFile
)

// completion 保存补全弹窗的临时 UI 状态。
type completion struct {
	kind completionKind

	// 命令补全专用：过滤后的命令列表
	items []string

	// 文件补全专用
	atByteIndex   int      // @ 在 input.Value() 中的字节偏移
	query         string   // @ 之后到词尾的完整文本（含路径前缀）
	searchDir     string   // 解析出的搜索目录（用于判断是否需要重载）
	prefix        string   // searchDir 内的文件名前缀过滤
	allItems      []string // 目录内加载到的全部条目
	filteredItems []string // 按 prefix 过滤后的条目

	selectedIndex int
	loading       bool
}

// visibleItems 返回当前应展示在弹窗中的候选列表。
func (c *completion) visibleItems() []string {
	if c.kind == completionKindFile {
		return c.filteredItems
	}
	return c.items
}

// navigateUp 向上移动选中光标。
func (c *completion) navigateUp() {
	if c.selectedIndex > 0 {
		c.selectedIndex--
	}
}

// navigateDown 向下移动选中光标。
func (c *completion) navigateDown() {
	items := c.visibleItems()
	if c.selectedIndex < len(items)-1 {
		c.selectedIndex++
	}
}

// ──────────────────────────────────────────────────────────────────────────────
// 触发检测
// ──────────────────────────────────────────────────────────────────────────────

// detectAtTrigger 在 value 中找到最末尾的词边界 @ 触发点。
// 词边界条件：@ 位于字符串开头，或前一个字符为空白符。
// query 为 @ 之后到字符串末尾的内容；query 内不能含空白符（否则说明词已结束）。
// 如果未找到满足条件的 @，返回 (-1, "")。
func detectAtTrigger(value string) (atByteIndex int, query string) {
	runes := []rune(value)
	n := len(runes)
	if n == 0 {
		return -1, ""
	}

	// 从末尾向前扫描，找到当前"词"的起始位置。
	// 词 = 连续的非空白字符序列（位于末尾）。
	wordStart := n // 默认：末尾是空白，没有当前词
	for i := n - 1; i >= 0; i-- {
		if unicode.IsSpace(runes[i]) {
			wordStart = i + 1
			break
		}
		wordStart = i
	}

	if wordStart >= n {
		return -1, "" // 当前词为空（末尾是空白）
	}

	// 当前词必须以 @ 开头
	if runes[wordStart] != '@' {
		return -1, ""
	}

	// 词边界：@ 在行首，或前一个字符为空白
	if wordStart > 0 && !unicode.IsSpace(runes[wordStart-1]) {
		return -1, "" // @ 紧跟非空白字符，不是词边界（如 "text@foo"）
	}

	// 计算 @ 在原始字节串中的偏移
	byteOff := 0
	for _, r := range runes[:wordStart] {
		byteOff += utf8.RuneLen(r)
	}

	// query = @ 之后的全部文本
	q := string(runes[wordStart+1:])
	return byteOff, q
}

// ──────────────────────────────────────────────────────────────────────────────
// 路径解析
// ──────────────────────────────────────────────────────────────────────────────

// resolveSearchDir 根据 @ 之后的 query 解析搜索目录和文件名前缀。
//
//   - @       → (cwd, "")
//   - @foo    → (cwd, "foo")
//   - @sub/   → (cwd/sub, "")
//   - @sub/f  → (cwd/sub, "f")
//   - @~/f    → (HOME, "f")
//   - @/etc/f → ("/etc", "f")
func resolveSearchDir(query string) (dir, prefix string) {
	cwd, _ := os.Getwd()
	if cwd == "" {
		cwd = "."
	}

	switch {
	case query == "" || query == ".":
		return cwd, ""

	case query == "~":
		home, _ := os.UserHomeDir()
		return home, ""

	case strings.HasPrefix(query, "~/"):
		home, err := os.UserHomeDir()
		if err != nil {
			return cwd, ""
		}
		return resolvePathParts(home, query[2:])

	case strings.HasPrefix(query, "/"):
		return resolvePathParts("/", query[1:])

	default:
		return resolvePathParts(cwd, query)
	}
}

// resolvePathParts 将 base/rest 分解为 (directory, filePrefix)。
// 若 rest 含路径分隔符，最后一段作为文件名前缀，其余拼入目录。
func resolvePathParts(base, rest string) (dir, prefix string) {
	if rest == "" {
		return base, ""
	}
	if !strings.Contains(rest, "/") {
		return base, rest
	}
	idx := strings.LastIndex(rest, "/")
	return filepath.Join(base, rest[:idx]), rest[idx+1:]
}

// ──────────────────────────────────────────────────────────────────────────────
// appModel 同步逻辑（在 app.go 的 isTextEditingKey 分支调用）
// ──────────────────────────────────────────────────────────────────────────────

// syncAtCompletion 检测 @ 触发并更新 m.completion。
// 需要重新加载文件时返回 tea.Cmd，否则返回 nil。
func (m *appModel) syncAtCompletion() tea.Cmd {
	// / 命令补全优先，不与 @ 同时激活
	if m.completion != nil && m.completion.kind == completionKindCommand {
		return nil
	}

	val := m.input.Value()
	atIdx, query := detectAtTrigger(val)

	if atIdx < 0 {
		// 没有触发点，清除文件补全
		if m.completion != nil && m.completion.kind == completionKindFile {
			m.clearCompletionAndRelayout()
		}
		return nil
	}

	searchDir, prefix := resolveSearchDir(query)
	useDefault := query == ""

	if m.completion == nil || m.completion.kind != completionKindFile || m.completion.searchDir != searchDir {
		// 目录发生变化或补全尚未创建：重新加载
		m.completion = &completion{
			kind:        completionKindFile,
			atByteIndex: atIdx,
			query:       query,
			searchDir:   searchDir,
			prefix:      prefix,
			loading:     true,
		}
		m.sessionPicker = nil
		return loadFilesInDirCmd(searchDir, prefix, useDefault)
	}

	// 同一目录：仅更新前缀和过滤结果
	m.completion.atByteIndex = atIdx
	m.completion.query = query
	m.completion.prefix = prefix
	filtered := filterByPrefix(m.completion.allItems, prefix)
	if useDefault && len(filtered) > 5 {
		filtered = filtered[:5]
	}
	m.completion.filteredItems = filtered
	if m.completion.selectedIndex >= len(filtered) {
		m.completion.selectedIndex = 0
	}
	return nil
}

// syncCommandCompletion 检测 / 命令补全并更新 m.completion。
func (m *appModel) syncCommandCompletion() {
	val := m.input.Value()
	if !strings.HasPrefix(val, "/") {
		if m.completion != nil && m.completion.kind == completionKindCommand {
			m.clearCompletionAndRelayout()
		}
		return
	}
	query := strings.TrimPrefix(val, "/")
	items := commandCompletionItems(query, m.commandRegistry)
	if len(items) == 0 {
		m.clearCompletionAndRelayout()
		return
	}
	if m.completion == nil || m.completion.kind != completionKindCommand {
		m.completion = &completion{kind: completionKindCommand, items: items, prefix: query}
	} else {
		m.completion.items = items
		m.completion.prefix = query
		if m.completion.selectedIndex >= len(items) {
			m.completion.selectedIndex = 0
		}
	}
}

// ──────────────────────────────────────────────────────────────────────────────
// 异步文件加载
// ──────────────────────────────────────────────────────────────────────────────

// loadFilesInDirCmd 异步列出 searchDir 目录下的条目，用 filePrefix 过滤。
// useDefault=true 时最多返回前 5 条。
func loadFilesInDirCmd(searchDir, filePrefix string, useDefault bool) tea.Cmd {
	return func() tea.Msg {
		entries, err := os.ReadDir(searchDir)
		if err != nil {
			return fileCompletionLoadedMsg{searchDir: searchDir}
		}

		var all []string
		for _, e := range entries {
			name := e.Name()
			if strings.HasPrefix(name, ".") {
				continue
			}
			if e.IsDir() {
				all = append(all, name+"/")
			} else {
				all = append(all, name)
			}
		}

		filtered := filterByPrefix(all, filePrefix)
		if useDefault && filePrefix == "" && len(filtered) > 5 {
			filtered = filtered[:5]
		}

		return fileCompletionLoadedMsg{
			searchDir: searchDir,
			items:     all,
			filtered:  filtered,
		}
	}
}

// filterByPrefix 筛选以 prefix 开头的条目（大小写不敏感）。
func filterByPrefix(items []string, prefix string) []string {
	if prefix == "" {
		out := make([]string, len(items))
		copy(out, items)
		return out
	}
	lower := strings.ToLower(prefix)
	var out []string
	for _, item := range items {
		if strings.HasPrefix(strings.ToLower(item), lower) {
			out = append(out, item)
		}
	}
	return out
}

// ──────────────────────────────────────────────────────────────────────────────
// 命令补全构造
// ──────────────────────────────────────────────────────────────────────────────

// newCommandCompletion 创建命令补全（同步）。
func newCommandCompletion(prefix string, registry *CommandRegistry) *completion {
	items := commandCompletionItems(prefix, registry)
	if len(items) == 0 {
		return nil
	}
	return &completion{
		kind:   completionKindCommand,
		items:  items,
		prefix: prefix,
	}
}

// commandCompletionItems 从注册表中筛选匹配前缀的命令名。
func commandCompletionItems(prefix string, registry *CommandRegistry) []string {
	if registry == nil {
		return nil
	}
	var items []string
	for _, name := range registry.order {
		if prefix == "" || strings.HasPrefix(name, "/"+prefix) {
			items = append(items, name)
		}
	}
	return items
}

// ──────────────────────────────────────────────────────────────────────────────
// 补全确认 — 写回输入框
// ──────────────────────────────────────────────────────────────────────────────

// applyFileCompletion 将选中文件写回输入框，只替换 @query 段，保留之前的文本。
// trailingSpace=true（Enter）在路径后追加空格以结束引用；false（Tab）不追加，光标停在路径末尾。
func (m appModel) applyFileCompletion(selected string, trailingSpace bool) appModel {
	if m.completion == nil {
		return m
	}
	val := m.input.Value()
	atIdx, query := detectAtTrigger(val)
	if atIdx < 0 {
		return m
	}

	before := val[:atIdx]
	ref := buildAtRef(query, m.completion.searchDir, selected)
	suffix := ""
	if trailingSpace {
		suffix = " "
	}
	m.input.SetValue(before + ref + suffix)
	m.input.CursorEnd()
	m.relayout()
	return m
}

// buildAtRef 根据原始 query 和 selected 构造 @path 引用。
// 保留 query 中的路径前缀（如 @~/ 或 @/），只替换最末的文件名片段。
func buildAtRef(query, searchDir, selected string) string {
	// 找到最后一个 / 的位置，保留 @ + 路径前缀
	if idx := strings.LastIndex(query, "/"); idx >= 0 {
		return "@" + query[:idx+1] + selected
	}
	// 没有 / 分隔符，直接 @selected
	_ = searchDir
	return "@" + selected
}

// applyCommandCompletion 将命令填入输入框。
func (m appModel) applyCommandCompletion(selected string) appModel {
	m.input.SetValue(selected + " ")
	m.input.CursorEnd()
	return m
}

func (m *appModel) clearCompletionAndRelayout() {
	if m.completion == nil {
		return
	}
	m.completion = nil
	m.relayout()
}

// ──────────────────────────────────────────────────────────────────────────────
// 渲染
// ──────────────────────────────────────────────────────────────────────────────

// renderCompletionBox 渲染补全弹窗（显示在输入框上方）。
func (m appModel) renderCompletionBox() string {
	if m.completion == nil {
		return ""
	}
	width := maxInt(32, m.width-2)
	return completionPanelStyle.Width(width).Render(m.renderCompletionContent())
}

// renderCompletionContent 渲染补全弹窗内容。
func (m appModel) renderCompletionContent() string {
	c := m.completion
	var title string
	switch c.kind {
	case completionKindCommand:
		title = wizardTitleStyle.Render("Commands")
	case completionKindFile:
		title = wizardTitleStyle.Render("Files")
	}
	lines := []string{title}

	if c.loading {
		lines = append(lines, "  Loading...")
		return strings.Join(lines, "\n")
	}

	visible := c.visibleItems()
	if len(visible) == 0 {
		lines = append(lines, "  No matches.")
		return strings.Join(lines, "\n")
	}

	maxVisible := 8
	start := 0
	if c.selectedIndex >= maxVisible {
		start = c.selectedIndex - maxVisible + 1
	}
	end := start + maxVisible
	if end > len(visible) {
		end = len(visible)
	}

	for i := start; i < end; i++ {
		label := visible[i]
		if i == c.selectedIndex {
			lines = append(lines, selectedProviderStyle.Render(fmt.Sprintf("> %s", label)))
		} else {
			lines = append(lines, unselectedProviderStyle.Render(fmt.Sprintf("  %s", label)))
		}
	}
	return strings.Join(lines, "\n")
}

// ──────────────────────────────────────────────────────────────────────────────
// 兼容占位（避免外部调用编译错误）
// ──────────────────────────────────────────────────────────────────────────────

// newFileCompletion 兼容旧调用签名。
func newFileCompletion(_ string) *completion {
	return &completion{kind: completionKindFile, loading: true}
}

// loadFileCompletionCmd 兼容旧调用，加载 cwd 默认 5 个文件。
func loadFileCompletionCmd() tea.Cmd {
	cwd, _ := os.Getwd()
	return loadFilesInDirCmd(cwd, "", true)
}

// 本文件定义输入框提交、斜杠命令、终端模式和历史输入导航行为。
package bubble

import (
	"github.com/charmbracelet/bubbles/textarea"
	tea "github.com/charmbracelet/bubbletea"
	"strings"
	"time"
)

// handleSubmit 处理 Enter 提交，根据输入内容分派到聊天、命令或终端执行路径。
func (m appModel) handleSubmit() (tea.Model, tea.Cmd) {
	m.reconcileLegacyRunningState()
	var line string
	var ok bool
	m, line, ok = m.consumeSubmittedInput()
	if !ok {
		return m, nil
	}

	if isExitCommandInput(line) {
		m.rememberInputHistory(line)
		_, cmd := m.handleCommand(line)
		return m, cmd
	}
	if line == "!" {
		m.toggleTerminalMode()
		return m, nil
	}
	if m.terminalMode {
		m.rememberInputHistory(line)
		return m.submitShellCommand(line)
	}
	if command, ok := shellCommandFromBang(line); ok {
		if m.isWorkRunning() {
			m.addEntry(transcriptEntry{kind: entrySystem, title: "busy", body: "terminal commands are unavailable while a turn is running"})
			return m, nil
		}
		m.rememberInputHistory(line)
		return m.submitShellCommand(command)
	}

	if handled, cmd := m.handleCommand(line); handled {
		return m, cmd
	}

	if m.isModelWorkRunning() {
		return m.submitSupplement(line), nil
	}
	if m.isTerminalWorkRunning() {
		m.addEntry(transcriptEntry{kind: entrySystem, title: "busy", body: "chat is unavailable while a terminal command is running"})
		return m, nil
	}

	m.rememberInputHistory(line)
	return m.startChatTurn(line)
}

func (m appModel) handleQueueSubmit() (tea.Model, tea.Cmd) {
	var line string
	var ok bool
	m, line, ok = m.consumeSubmittedInput()
	if !ok {
		return m, nil
	}
	if m.isModelWorkRunning() {
		return m.queueChatInput(line), nil
	}
	m.input.SetValue(line)
	m.input.CursorEnd()
	m.syncInputMode()
	m.relayout()
	return m, nil
}

func (m appModel) consumeSubmittedInput() (appModel, string, bool) {
	line := strings.TrimSpace(m.input.Value())
	if line == "" {
		return m, "", false
	}
	m.input.Reset()
	m.resetHistoryNavigation()
	m.syncInputMode()
	m.relayout()

	if continued, text := splitContinuation(line); continued {
		m.rememberInputHistory(line)
		m.pending = append(m.pending, text)
		m.refreshViewport()
		return m, "", false
	}

	if len(m.pending) > 0 {
		m.pending = append(m.pending, line)
		line = strings.Join(m.pending, "\n")
		m.pending = nil
	}
	return m, line, true
}

// handleCommand 处理内置 TUI 命令。除 exit/quit 外，命令仍要求以斜杠开头。
func (m *appModel) handleCommand(line string) (bool, tea.Cmd) {
	trimmed := strings.TrimSpace(line)
	if !strings.HasPrefix(trimmed, "/") && !isBareExitCommand(trimmed) {
		return false, nil
	}
	if m.commandRegistry == nil {
		m.commandRegistry = NewCommandRegistry()
	}
	return m.commandRegistry.Dispatch(m, line)
}

func isExitCommandInput(line string) bool {
	trimmed := strings.TrimSpace(line)
	return trimmed == "/exit" || trimmed == "/quit" || isBareExitCommand(trimmed)
}

func isBareExitCommand(line string) bool {
	return line == "exit" || line == "quit"
}

// toggleTerminalMode 切换持续终端模式，并在 transcript 中写入状态提示。
func (m *appModel) toggleTerminalMode() {
	m.terminalMode = !m.terminalMode
	m.pending = nil
	m.activeAssistant = -1
	m.applyCursorAnimation()
	state := "terminal mode disabled"
	if m.terminalMode {
		state = "terminal mode enabled"
	}
	m.addEntry(transcriptEntry{
		kind:  entrySystem,
		title: "terminal",
		body:  state,
	})
}

// isTerminalInputActive 判断当前输入框是否需要展示终端模式视觉状态。
func (m appModel) isTerminalInputActive() bool {
	return m.terminalMode || m.terminalPreview
}

// hasMultilineInput 判断当前输入是否处于多行输入或续行状态。
func (m appModel) hasMultilineInput() bool {
	return len(m.pending) > 0 || strings.Contains(m.input.Value(), "\n")
}

// syncInputMode 根据当前文本同步一次性终端预览状态。
func (m *appModel) syncInputMode() {
	m.terminalPreview = hasBangPrefix(m.input.Value())
}

// handleInputVerticalNavigation 让上下键先在多行文本内移动，抵达边界后再切换历史输入。
func (m appModel) handleInputVerticalNavigation(direction int) (tea.Model, tea.Cmd) {
	if m.isTerminalWorkRunning() {
		return m, nil
	}

	if direction < 0 {
		if canMoveTextareaUp(m.input) {
			return m.updateInputWithKey(tea.KeyMsg{Type: tea.KeyUp})
		}
		if !textareaCursorAtStart(m.input) {
			m.input.CursorStart()
			m.syncInputMode()
			m.applyCursorAnimation()
			return m, nil
		}
		return m.handleHistoryNavigation(-1)
	}

	if canMoveTextareaDown(m.input) {
		return m.updateInputWithKey(tea.KeyMsg{Type: tea.KeyDown})
	}
	if !textareaCursorAtEnd(m.input) {
		m.input.CursorEnd()
		m.historyDownLock = false
		m.syncInputMode()
		m.applyCursorAnimation()
		return m, nil
	}
	if m.historyDownLock && m.historyIndex != -1 {
		m.historyDownLock = false
		return m, nil
	}
	return m.handleHistoryNavigation(1)
}

func (m appModel) submitSupplement(line string) appModel {
	line = strings.TrimSpace(line)
	if line == "" {
		return m
	}
	m.rememberInputHistory(line)
	submitter, ok := m.runner.(SupplementSubmitter)
	if !ok || !submitter.SubmitSupplement(line) {
		m.addEntry(transcriptEntry{
			kind:  entrySystem,
			title: "supplement",
			body:  "runner does not support running-turn supplements",
		})
		return m
	}
	m.addEntry(transcriptEntry{
		kind:  entryUser,
		title: "you (supplement)",
		body:  line,
	})
	return m
}

// startChatTurn records and starts a model turn when the guard is idle.
func (m appModel) startChatTurn(line string) (appModel, tea.Cmd) {
	line = strings.TrimSpace(line)
	if line == "" {
		return m, nil
	}
	if !m.queryGuard.StartModel() {
		m.addEntry(transcriptEntry{kind: entrySystem, title: "busy", body: "assistant is already running"})
		return m, nil
	}
	m.addEntry(transcriptEntry{
		kind:  entryUser,
		title: "you",
		body:  line,
	})
	m.turnStartedAt = time.Now()
	m.syncRunningFlags()
	m.activeAssistant = -1
	return m, runTurnCmd(m.ctx, m.runner, line)
}

// queueChatInput records a chat input for FIFO execution after the active turn.
func (m appModel) queueChatInput(line string) appModel {
	line = strings.TrimSpace(line)
	if line == "" {
		return m
	}
	m.rememberInputHistory(line)
	if m.chatQueue.Enqueue(line) {
		m.addEntry(transcriptEntry{
			kind:  entryUser,
			title: "you (queued)",
			body:  line,
		})
		m.addEntry(transcriptEntry{
			kind:  entrySystem,
			title: "queued",
			body:  "queued for next turn",
		})
	}
	return m
}

// updateInputWithKey 将按键交给 textarea 处理，并同步输入模式、布局和光标动画。
func (m appModel) updateInputWithKey(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
	input, cmd := m.input.Update(msg)
	m.input = input
	m.syncInputMode()
	m.relayout()
	m.applyCursorAnimation()
	return m, cmd
}

// canMoveTextareaUp 判断 textarea 光标是否还能向上移动到上一行或上方可视行。
func canMoveTextareaUp(input textarea.Model) bool {
	lineInfo := input.LineInfo()
	return input.Line() > 0 || lineInfo.RowOffset > 0
}

// canMoveTextareaDown 判断 textarea 光标是否还能向下移动到下一行或下方可视行。
func canMoveTextareaDown(input textarea.Model) bool {
	lineInfo := input.LineInfo()
	return input.Line() < input.LineCount()-1 || lineInfo.RowOffset < lineInfo.Height-1
}

// textareaCursorAtStart 判断 textarea 光标是否位于当前输入的逻辑开头。
func textareaCursorAtStart(input textarea.Model) bool {
	if canMoveTextareaUp(input) {
		return false
	}
	lineInfo := input.LineInfo()
	cursorLine := input.Line()
	copyInput := input
	copyInput.CursorStart()
	startInfo := copyInput.LineInfo()
	return cursorLine == copyInput.Line() &&
		lineInfo.RowOffset == startInfo.RowOffset &&
		lineInfo.ColumnOffset == startInfo.ColumnOffset
}

// textareaCursorAtEnd 判断 textarea 光标是否位于当前输入的逻辑末尾。
func textareaCursorAtEnd(input textarea.Model) bool {
	if canMoveTextareaDown(input) {
		return false
	}
	lineInfo := input.LineInfo()
	cursorLine := input.Line()
	copyInput := input
	copyInput.CursorEnd()
	endInfo := copyInput.LineInfo()
	return cursorLine == copyInput.Line() &&
		lineInfo.RowOffset == endInfo.RowOffset &&
		lineInfo.ColumnOffset == endInfo.ColumnOffset
}

// handleHistoryNavigation 在输入边界处切换历史记录，并保留进入历史前的草稿。
func (m appModel) handleHistoryNavigation(direction int) (tea.Model, tea.Cmd) {
	if m.running || len(m.inputHistory) == 0 {
		return m, nil
	}

	if direction < 0 {
		m.historyDownLock = false
		if m.historyIndex == -1 {
			m.historyDraft = m.input.Value()
			m.historyIndex = len(m.inputHistory) - 1
		} else if m.historyIndex > 0 {
			m.historyIndex--
		}
		m.input.SetValue(m.inputHistory[m.historyIndex])
		m.input.CursorEnd()
		m.syncInputMode()
		m.relayout()
		m.applyCursorAnimation()
		return m, nil
	}

	if m.historyIndex == -1 {
		return m, nil
	}
	if m.historyIndex < len(m.inputHistory)-1 {
		m.historyIndex++
		m.input.SetValue(m.inputHistory[m.historyIndex])
		m.historyDownLock = true
	} else {
		m.historyIndex = -1
		m.input.SetValue(m.historyDraft)
		m.historyDraft = ""
		m.historyDownLock = false
	}
	m.input.CursorEnd()
	m.syncInputMode()
	m.relayout()
	m.applyCursorAnimation()
	return m, nil
}

// rememberInputHistory 记录一条非空且不重复的用户输入历史。
func (m *appModel) rememberInputHistory(line string) {
	line = strings.TrimSpace(line)
	if line == "" {
		return
	}
	if len(m.inputHistory) > 0 && m.inputHistory[len(m.inputHistory)-1] == line {
		return
	}
	m.inputHistory = append(m.inputHistory, line)
}

// resetHistoryNavigation 清除当前历史浏览状态，回到普通编辑模式。
func (m *appModel) resetHistoryNavigation() {
	m.historyIndex = -1
	m.historyDraft = ""
	m.historyDownLock = false
}

// submitShellCommand 提交终端命令，先写入 transcript，再异步执行 bash。
func (m appModel) submitShellCommand(command string) (tea.Model, tea.Cmd) {
	command = strings.TrimSpace(command)
	if command == "" {
		return m, nil
	}
	if !m.queryGuard.StartTerminal() {
		m.addEntry(transcriptEntry{kind: entrySystem, title: "busy", body: "terminal commands are unavailable while work is running"})
		return m, nil
	}
	m.addEntry(transcriptEntry{
		kind:  entryTool,
		title: "terminal",
		body:  "$ " + command,
	})
	m.syncRunningFlags()
	m.activeAssistant = -1
	return m, runShellCmd(m.ctx, command)
}

// 本文件定义聊天历史 transcript 的追加、刷新和逐条渲染逻辑。
package bubble

import (
	"encoding/json"
	"github.com/charmbracelet/lipgloss"
	"strings"
	"time"
)

const toolExpandDuration = 650 * time.Millisecond

// appendAssistantDelta 将模型流式增量追加到当前 assistant 消息，必要时新建消息。
func (m *appModel) appendAssistantDelta(delta string) {
	if delta == "" {
		return
	}
	if m.activeAssistant < 0 || m.activeAssistant >= len(m.transcript) || m.transcript[m.activeAssistant].kind != entryAssistant {
		m.transcript = append(m.transcript, transcriptEntry{
			kind:      entryAssistant,
			title:     "assistant",
			citations: m.consumePendingToolCitations(),
			createdAt: m.animationNow(),
		})
		m.activeAssistant = len(m.transcript) - 1
	} else if len(m.pendingToolCites) > 0 {
		m.transcript[m.activeAssistant].citations = append(m.transcript[m.activeAssistant].citations, m.consumePendingToolCitations()...)
	}
	m.transcript[m.activeAssistant].body += delta
	m.refreshViewport()
}

// appendThinkingDelta 将模型 thinking 增量追加到 transcript，渲染时由 showThinking 控制显隐。
func (m *appModel) appendThinkingDelta(delta string) {
	if delta == "" {
		return
	}
	m.activeAssistant = -1
	if len(m.transcript) == 0 || m.transcript[len(m.transcript)-1].kind != entryThinking {
		m.transcript = append(m.transcript, transcriptEntry{
			kind:      entryThinking,
			title:     "thinking",
			createdAt: m.animationNow(),
		})
	}
	m.transcript[len(m.transcript)-1].body += delta
	m.refreshViewport()
}

// addEntry 追加一条 transcript 记录并刷新滚动区。
func (m *appModel) addEntry(entry transcriptEntry) {
	if entry.createdAt.IsZero() {
		entry.createdAt = m.animationNow()
	}
	m.transcript = append(m.transcript, entry)
	m.refreshViewport()
}

func (m appModel) animationNow() time.Time {
	if !m.cursorFrameAt.IsZero() {
		return m.cursorFrameAt
	}
	return time.Now()
}

func (m *appModel) consumePendingToolCitations() []toolCitation {
	if len(m.pendingToolCites) == 0 {
		return nil
	}
	cites := append([]toolCitation(nil), m.pendingToolCites...)
	m.pendingToolCites = nil
	return cites
}

func (m *appModel) recordToolCallCitation(toolUseID, name string, input json.RawMessage) {
	cite := newToolCallCitation(toolUseID, name, input)
	if idx := m.lastAssistantCitationHostIndex(); idx >= 0 {
		m.transcript[idx].citations = append(m.transcript[idx].citations, cite)
	} else {
		m.transcript = append(m.transcript, transcriptEntry{
			kind:      entryAssistant,
			title:     "assistant",
			citations: []toolCitation{cite},
			createdAt: m.animationNow(),
		})
	}
	m.refreshViewport()
}

func (m *appModel) recordToolCallEntry(toolUseID, name string, input json.RawMessage, oldContent string) {
	name = strings.TrimSpace(name)
	if name == "" {
		name = "tool"
	}
	m.addEntry(transcriptEntry{
		kind:      entryTool,
		title:     "tool",
		body:      formatRunningToolCallBody(name, input, oldContent),
		toolUseID: strings.TrimSpace(toolUseID),
		toolName:  name,
		createdAt: m.animationNow(),
	})
}

func (m *appModel) recordToolResultEntry(toolUseID, name, status string, isError bool) {
	name = strings.TrimSpace(name)
	if name == "" {
		name = "tool"
	}
	status = strings.TrimSpace(status)
	if status == "" {
		status = "ok"
	}
	result := toolEntryResult{
		toolUseID: strings.TrimSpace(toolUseID),
		name:      name,
		status:    status,
		isError:   isError,
	}
	for idx := len(m.transcript) - 1; idx >= 0; idx-- {
		entry := &m.transcript[idx]
		if !toolEntryMatchesResult(*entry, result) {
			continue
		}
		entry.title = "tool"
		entry.body = completeRunningToolCallBody(entry.body, status)
		entry.isError = isError
		m.refreshViewport()
		return
	}
	m.addEntry(transcriptEntry{
		kind:      entryTool,
		title:     "tool",
		body:      formatToolResultBody(name, status, ""),
		isError:   isError,
		toolUseID: strings.TrimSpace(toolUseID),
		toolName:  name,
		createdAt: m.animationNow(),
	})
}

func (m *appModel) recordToolResultCitation(toolUseID, name, status, content string, isError bool) {
	cite := newToolResultCitation(toolUseID, name, status, content, isError)
	for entryIdx := len(m.transcript) - 1; entryIdx >= 0; entryIdx-- {
		entry := &m.transcript[entryIdx]
		if entry.kind == entryUser {
			break
		}
		if entry.kind != entryAssistant {
			continue
		}
		for citeIdx := len(entry.citations) - 1; citeIdx >= 0; citeIdx-- {
			if toolCitationMatchesResult(entry.citations[citeIdx], cite) {
				entry.citations[citeIdx].status = cite.status
				entry.citations[citeIdx].preview = cite.preview
				entry.citations[citeIdx].isError = cite.isError
				m.refreshViewport()
				return
			}
		}
	}
	if idx := m.lastAssistantCitationHostIndex(); idx >= 0 {
		m.transcript[idx].citations = append(m.transcript[idx].citations, cite)
	} else {
		m.transcript = append(m.transcript, transcriptEntry{
			kind:      entryAssistant,
			title:     "assistant",
			citations: []toolCitation{cite},
			createdAt: m.animationNow(),
		})
	}
	m.refreshViewport()
}

type toolEntryResult struct {
	toolUseID string
	name      string
	status    string
	isError   bool
}

func toolEntryMatchesResult(entry transcriptEntry, result toolEntryResult) bool {
	if entry.kind != entryTool || entry.title != "tool" {
		return false
	}
	if !strings.Contains(firstToolEntryLine(entry.body), "running") {
		return false
	}
	if entry.toolUseID != "" || result.toolUseID != "" {
		return entry.toolUseID != "" && entry.toolUseID == result.toolUseID
	}
	return strings.EqualFold(entry.toolName, result.name)
}

func toolCitationMatchesResult(running, result toolCitation) bool {
	if running.status != "running" {
		return false
	}
	if running.toolUseID != "" || result.toolUseID != "" {
		return running.toolUseID != "" && running.toolUseID == result.toolUseID
	}
	return strings.EqualFold(running.name, result.name)
}

func (m appModel) lastAssistantCitationHostIndex() int {
	for i := len(m.transcript) - 1; i >= 0; i-- {
		switch m.transcript[i].kind {
		case entryAssistant:
			return i
		case entryUser:
			return -1
		}
	}
	return -1
}

func assistantEntryIsRenderable(entry transcriptEntry) bool {
	if entry.kind != entryAssistant {
		return true
	}
	if sanitizeAssistantVisibleBody(entry.body) != "" {
		return true
	}
	for _, cite := range entry.citations {
		if strings.TrimSpace(cite.name) != "" {
			return true
		}
	}
	return false
}

// refreshViewport 将 transcript 重新渲染到 viewport，并滚动到底部。
func (m *appModel) refreshViewport() {
	content := m.renderTranscriptContent()
	if m.selectionActive {
		content = m.renderTranscriptSelection(content)
	}
	m.viewport.SetContent(content)
	if !m.selectionActive {
		m.viewport.GotoBottom()
	}
}

// refreshViewportPreservingOffset 刷新 transcript 内容，但保留用户当前滚动位置。
func (m *appModel) refreshViewportPreservingOffset() {
	offset := m.viewport.YOffset
	content := m.renderTranscriptContent()
	if m.selectionActive {
		content = m.renderTranscriptSelection(content)
	}
	m.viewport.SetContent(content)
	m.viewport.SetYOffset(offset)
}

func (m appModel) renderTranscriptContent() string {
	return renderTranscriptAt(m.transcript, maxInt(20, m.viewport.Width), m.showThinking, m.animationNow())
}

func (m appModel) hasActiveTranscriptAnimation() bool {
	now := m.animationNow()
	for _, entry := range m.transcript {
		if entry.kind == entryTool && !entry.createdAt.IsZero() && now.Sub(entry.createdAt) < toolExpandDuration {
			return true
		}
	}
	return false
}

// renderTranscript 把多条 transcript 记录渲染为 viewport 内容。
func renderTranscript(entries []transcriptEntry, width int, showThinking bool) string {
	return renderTranscriptAt(entries, width, showThinking, time.Time{})
}

func renderTranscriptAt(entries []transcriptEntry, width int, showThinking bool, at time.Time) string {
	if len(entries) == 0 {
		return ""
	}
	parts := make([]string, 0, len(entries))
	for _, entry := range entries {
		if entry.kind == entryThinking && !showThinking {
			continue
		}
		if !assistantEntryIsRenderable(entry) {
			continue
		}
		parts = append(parts, renderEntryAt(entry, width, at))
	}
	return strings.Join(parts, "\n\n")
}

// renderEntry 渲染一条带标签和统一缩进的 transcript 记录。
func renderEntry(entry transcriptEntry, width int) string {
	return renderEntryAt(entry, width, time.Time{})
}

func renderEntryAt(entry transcriptEntry, width int, at time.Time) string {
	const entryGutter = "  "
	label := labelStyle(entry.kind).Render(entry.title)
	bodyWidth := maxInt(20, width-lipgloss.Width(entryGutter))
	body := renderEntryBodyAt(entry, bodyWidth, at)
	if entry.kind == entryTool {
		if body == "" {
			return ""
		}
		return indentLines(body, entryGutter)
	}
	if body == "" {
		return entryGutter + label
	}
	return indentLines(label+"\n"+body, entryGutter)
}

// renderEntryBody 按消息类型渲染正文，assistant 消息会走 Markdown 渲染。
func renderEntryBody(entry transcriptEntry, width int) string {
	return renderEntryBodyAt(entry, width, time.Time{})
}

func renderEntryBodyAt(entry transcriptEntry, width int, at time.Time) string {
	body := strings.TrimRight(entry.body, "\n")
	if entry.kind == entryAssistant {
		body = sanitizeAssistantVisibleBody(body)
		return renderAssistantBodyWithCitations(body, width, entry.citations)
	}
	if body == "" {
		return ""
	}
	if entry.kind == entryThinking {
		return thinkingBodyStyle.Width(width).Render(body)
	}
	if entry.kind == entryTool {
		isError := entry.isError
		isResult := toolEntryHasCompletedStatus(entry)
		prog := toolExpandProgress(entry, at)
		switch {
		case isError:
			return renderToolEntryBodyWithMarker(entry.body, width, prog, toolErrorBorderStyle, "!")
		case isResult:
			return renderToolEntryBodyWithMarker(entry.body, width, prog, toolResultBorderStyle, "✓")
		default:
			return renderToolEntryBody(entry.body, width, prog)
		}
	}
	return bodyStyle.Width(width).Render(body)
}

func toolEntryHasCompletedStatus(entry transcriptEntry) bool {
	line := firstToolEntryLine(entry.body)
	parts := splitToolSummaryParts(line)
	return len(parts) >= 2 && strings.EqualFold(parts[1], "ok")
}

func renderAssistantBodyWithCitations(body string, width int, citations []toolCitation) string {
	citations = compactToolCitations(citations)
	rendered := renderMarkdown(body, width)
	if len(citations) == 0 {
		return rendered
	}
	quote := renderToolCitationQuote(citations, width)
	if quote == "" {
		return rendered
	}
	if rendered == "" {
		return quote
	}
	return rendered + "\n" + quote
}

func newToolCallCitation(toolUseID, name string, input json.RawMessage) toolCitation {
	name = strings.TrimSpace(name)
	if name == "" {
		name = "tool"
	}
	fields := toolInputFields(input)
	return toolCitation{
		toolUseID: strings.TrimSpace(toolUseID),
		name:      name,
		target:    primaryToolInput(name, fields),
		status:    "running",
	}
}

func newToolResultCitation(toolUseID, name, status, content string, isError bool) toolCitation {
	name = strings.TrimSpace(name)
	if name == "" {
		name = "tool"
	}
	status = strings.TrimSpace(status)
	if status == "" {
		status = "ok"
	}
	return toolCitation{
		toolUseID: strings.TrimSpace(toolUseID),
		name:      name,
		status:    status,
		preview:   summarizeToolContent(content),
		isError:   isError,
	}
}

func compactToolCitations(citations []toolCitation) []toolCitation {
	out := make([]toolCitation, 0, len(citations))
	for _, cite := range citations {
		cite.name = strings.TrimSpace(cite.name)
		cite.target = strings.TrimSpace(cite.target)
		cite.status = strings.TrimSpace(cite.status)
		cite.preview = strings.TrimSpace(cite.preview)
		if cite.name == "" {
			continue
		}
		if cite.status == "" {
			cite.status = "ok"
		}
		out = append(out, cite)
	}
	return out
}

func renderToolCitationQuote(citations []toolCitation, width int) string {
	lines := make([]string, 0, len(citations))
	contentWidth := maxInt(1, width-2)
	for _, cite := range citations {
		if line := renderToolCitationQuoteLine(cite, contentWidth); line != "" {
			lines = append(lines, toolCitationQuoteBorderStyle.Render("│")+" "+line)
		}
	}
	if len(lines) == 0 {
		return ""
	}
	return strings.Join(lines, "\n")
}

func renderToolCitationQuoteLine(cite toolCitation, width int) string {
	name := strings.TrimSpace(cite.name)
	if name == "" {
		return ""
	}
	key := toolCitationKeyStyle.Render("[" + name + "]")
	status := toolCitationStatusStyle(cite).Render(toolCitationStatusText(cite))
	target := strings.TrimSpace(cite.target)
	lineWidth := lipgloss.Width("["+name+"] ") + lipgloss.Width(toolCitationStatusText(cite))
	if target == "" {
		return key + " " + status
	}
	targetWidth := maxInt(1, width-lineWidth-lipgloss.Width(" · "))
	return key + " " + status + toolCitationStyle.Render(" · "+truncateDisplayWidth(target, targetWidth))
}

func toolCitationStatusText(cite toolCitation) string {
	switch {
	case cite.isError || strings.EqualFold(cite.status, "error"):
		return "error"
	case strings.EqualFold(cite.status, "running"):
		return "running"
	default:
		return "ok"
	}
}

func toolCitationStatusStyle(cite toolCitation) lipgloss.Style {
	if cite.isError || strings.EqualFold(cite.status, "error") {
		return toolCitationErrorStyle
	}
	if strings.EqualFold(cite.status, "running") {
		return toolCitationStyle
	}
	return toolCitationOKStyle
}

// renderToolEntryBodyWithStyle renders a tool entry in blockquote style using the given border style.
func renderToolEntryBodyWithStyle(body string, width int, progress float64, borderStyle lipgloss.Style) string {
	return renderToolEntryBodyWithMarker(body, width, progress, borderStyle, "▸")
}

func renderToolEntryBodyWithMarker(body string, width int, progress float64, borderStyle lipgloss.Style, marker string) string {
	body = strings.TrimRight(body, "\n")
	summary, detail := splitToolSummary(body)
	contentWidth := toolEntryContentWidth(width, borderStyle)
	headerStyle := toolHeaderStyle
	switch marker {
	case "✓":
		headerStyle = lipgloss.NewStyle().Foreground(colorManager.LipglossColor(colorLabelResult)).Bold(true)
	case "!":
		headerStyle = lipgloss.NewStyle().Foreground(colorManager.LipglossColor(colorLabelError)).Bold(true)
	}
	header := headerStyle.Render(marker + " " + summary)

	if detail == "" || progress <= 0 {
		return borderStyle.Width(contentWidth).Render(header)
	}

	detailLines := strings.Split(detail, "\n")
	visibleLines := maxInt(1, int(float64(len(detailLines))*progress+0.999))
	if visibleLines > len(detailLines) {
		visibleLines = len(detailLines)
	}
	content := header + "\n" + renderToolDetailLines(detailLines[:visibleLines], contentWidth)
	return borderStyle.Width(contentWidth).Render(content)
}

func toolEntryContentWidth(width int, borderStyle lipgloss.Style) int {
	return maxInt(1, width-borderStyle.GetHorizontalFrameSize()-toolEntryNoWrapSafetyCells)
}

const toolEntryNoWrapSafetyCells = transcriptPanelHorizontalFrame + 1

func renderToolDetailLines(lines []string, width int) string {
	diffRowWidth := diffDetailRowsWidth(lines, width)
	rendered := make([]string, 0, len(lines))
	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		style := toolDetailStyle
		renderedLine := "  " + trimmed
		isDiffLine := false
		switch {
		case strings.HasPrefix(trimmed, "@@"), strings.HasPrefix(trimmed, "---"), strings.HasPrefix(trimmed, "+++"):
			style = toolCitationStyle
		case diffDetailLineMarker(trimmed) == "+":
			style = lipgloss.NewStyle().
				Foreground(lipgloss.Color("194")).
				Background(lipgloss.Color("22")).
				Bold(true)
			renderedLine = strings.TrimRight(line, " \t\r")
			isDiffLine = true
		case diffDetailLineMarker(trimmed) == "-":
			style = lipgloss.NewStyle().
				Foreground(lipgloss.Color("224")).
				Background(lipgloss.Color("52")).
				Bold(true)
			renderedLine = strings.TrimRight(line, " \t\r")
			isDiffLine = true
		}
		if isDiffLine {
			renderedLine = padDisplayWidth(truncateDisplayWidth(renderedLine, diffRowWidth), diffRowWidth)
			rendered = append(rendered, style.Render(renderedLine))
			continue
		}
		renderedLine = truncateDisplayWidth(renderedLine, width)
		rendered = append(rendered, style.Width(width).Render(renderedLine))
	}
	return strings.Join(rendered, "\n")
}

func diffDetailRowsWidth(lines []string, width int) int {
	maxAllowed := maxInt(1, width-2)
	maxLineWidth := 0
	for _, line := range lines {
		trimmed := strings.TrimSpace(line)
		if diffDetailLineMarker(trimmed) == "" {
			continue
		}
		maxLineWidth = maxInt(maxLineWidth, lipgloss.Width(truncateDisplayWidth(strings.TrimRight(line, " \t\r"), maxAllowed)))
	}
	if maxLineWidth == 0 {
		return maxAllowed
	}
	return minInt(maxAllowed, maxLineWidth)
}

func diffDetailLineMarker(line string) string {
	if strings.HasPrefix(line, "+") {
		return "+"
	}
	if strings.HasPrefix(line, "-") {
		return "-"
	}
	fields := strings.Fields(line)
	if len(fields) < 2 || !isDecimalNumber(fields[0]) {
		return ""
	}
	switch fields[1] {
	case "+", "-":
		return fields[1]
	default:
		return ""
	}
}

func isDecimalNumber(value string) bool {
	if value == "" {
		return false
	}
	for _, r := range value {
		if r < '0' || r > '9' {
			return false
		}
	}
	return true
}

// renderToolEntryBody renders a tool call entry with the default orange border.
// Called from renderEntryBodyAt for the "tool" title.
func renderToolEntryBody(body string, width int, progress float64) string {
	return renderToolEntryBodyWithStyle(body, width, progress, toolCallBorderStyle)
}

func splitToolSummary(body string) (string, string) {
	lines := strings.Split(strings.TrimRight(body, "\n"), "\n")
	if len(lines) == 0 {
		return "", ""
	}
	summary := strings.TrimSpace(lines[0])
	if len(lines) == 1 {
		return summary, ""
	}
	return summary, strings.Join(lines[1:], "\n")
}

func toolExpandProgress(entry transcriptEntry, at time.Time) float64 {
	if at.IsZero() || entry.createdAt.IsZero() {
		return 1
	}
	elapsed := at.Sub(entry.createdAt)
	if elapsed <= 0 {
		return 0
	}
	if elapsed >= toolExpandDuration {
		return 1
	}
	return easeOutCubic(float64(elapsed) / float64(toolExpandDuration))
}

// labelStyle 根据消息类型选择左侧标签样式。
func labelStyle(kind entryKind) lipgloss.Style {
	switch kind {
	case entryUser:
		return labelUserStyle
	case entryAssistant:
		return labelAssistantStyle
	case entryThinking:
		return labelThinkingStyle
	case entryTool:
		return labelToolStyle
	case entryError:
		return labelErrorStyle
	default:
		return labelSystemStyle
	}
}

// turnsCount 返回当前会话的用户消息轮次数。
func (m appModel) turnsCount() int {
	n := 0
	for _, e := range m.transcript {
		if e.kind == entryUser && e.title == "you" {
			n++
		}
	}
	return n
}

// indentLines 给多行文本逐行添加固定前缀。
func indentLines(text, prefix string) string {
	lines := strings.Split(text, "\n")
	for i, line := range lines {
		lines[i] = prefix + line
	}
	return strings.Join(lines, "\n")
}

// 本文件定义右侧 30% 面板的三个卡片渲染逻辑。
package bubble

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/charmbracelet/lipgloss"
	"gocode/internal/subagent"
)

const (
	pipelineCardMaxContentHeight = 12
	pipelineMaxStageRows         = 6
)

// pipelineArtifacts lists the 18 pipeline phases in order, each with display name and artifact filename.
// Artifact paths are relative to .pipeline-workspace/ (except Cleanup which is in the parent dir).
var pipelineArtifacts = [18][2]string{
	{"Brainstorm", "design.md"},
	{"Spec", "spec.json"},
	{"Plan", "plan.json"},
	{"Arch", "architecture.json"},
	{"Dispatch", "dispatch.json"},
	{"Execution", "execution-report.json"},
	{"Complexity", "execution-report.json"}, // shares artifact; detected via Merge existence
	{"Merge", "merge-report.json"},
	{"Validation", "validation-report.json"},
	{"Tree Class", "tree-classification.json"},
	{"Rubric Gen", "tree-rubrics.json"},
	{"Rubric Vfy", "tree-rubric-verification.json"},
	{"Rubric Rfn", "tree-rubrics-refined.json"},
	{"Grading", "tree-grading-individual.json"},
	{"QA", "qa-report.json"},
	{"Docs", "doc-report.json"},
	{"Assessment", "final-assessment.json"},
	{"Cleanup", ".pipeline-last-run-summary.json"}, // in parent of workspaceDir
}

// loadPipelineState scans workspaceDir and infers the current pipeline phase state.
func loadPipelineState(workspaceDir string, activeAfter time.Time) pipelineState {
	var s pipelineState
	s.activeIdx = -1
	latestArtifactAt := latestPipelineWorkspaceModTime(workspaceDir)
	if info, err := os.Stat(filepath.Join(filepath.Dir(workspaceDir), ".pipeline-last-run-summary.json")); err == nil {
		latestArtifactAt = maxTime(latestArtifactAt, info.ModTime())
	}

	// Read global iteration from execution-report.json
	iterFile := filepath.Join(workspaceDir, "execution-report.json")
	if data, err := os.ReadFile(iterFile); err == nil {
		var rep struct {
			Iteration int `json:"iteration"`
		}
		if json.Unmarshal(data, &rep) == nil && rep.Iteration > 0 {
			s.globalIter = rep.Iteration
		}
	}

	specExists := false
	if _, err := os.Stat(filepath.Join(workspaceDir, "spec.json")); err == nil {
		specExists = true
	}

	// Determine each phase's status
	lastDoneIdx := -1
	for i, pa := range pipelineArtifacts {
		artifactPath := filepath.Join(workspaceDir, pa[1])
		if pa[0] == "Cleanup" {
			artifactPath = filepath.Join(filepath.Dir(workspaceDir), pa[1])
		}
		_, err := os.Stat(artifactPath)
		exists := err == nil
		s.phases[i] = pipelinePhaseEntry{
			name:     pa[0],
			artifact: pa[1],
		}
		if exists {
			s.phases[i].status = phaseStatusDone
			s.doneCount++
			lastDoneIdx = i
		}
	}
	s.detected = specExists && pipelineWorkspaceIsActive(workspaceDir, latestArtifactAt, activeAfter)

	// Active phase = first phase after last done
	if s.detected && lastDoneIdx+1 < 18 {
		s.activeIdx = lastDoneIdx + 1
		s.phases[s.activeIdx].status = phaseStatusActive
		s.phases[s.activeIdx].iteration = s.globalIter
	}

	// Mark retry: Execution done + globalIter > 1 + Validation not done
	execDone := s.phases[5].status == phaseStatusDone
	validDone := s.phases[8].status == phaseStatusDone
	if execDone && s.globalIter > 1 && !validDone {
		for i := 5; i <= 8; i++ {
			if s.phases[i].status == phaseStatusPending {
				s.phases[i].status = phaseStatusRetry
			}
		}
	}
	return s
}

func latestPipelineWorkspaceModTime(workspaceDir string) time.Time {
	var latest time.Time
	_ = filepath.Walk(workspaceDir, func(_ string, info os.FileInfo, err error) error {
		if err != nil || info == nil {
			return nil
		}
		latest = maxTime(latest, info.ModTime())
		return nil
	})
	return latest
}

func pipelineWorkspaceIsActive(workspaceDir string, latestArtifactAt, activeAfter time.Time) bool {
	if activeAfter.IsZero() {
		return true
	}
	if pipelineActiveMarkerExists(workspaceDir, activeAfter) {
		return true
	}
	return !latestArtifactAt.IsZero() && !latestArtifactAt.Before(activeAfter)
}

func pipelineActiveMarkerExists(workspaceDir string, activeAfter time.Time) bool {
	for _, name := range []string{".active", ".pipeline-active", "active", "running", "pipeline.lock"} {
		info, err := os.Stat(filepath.Join(workspaceDir, name))
		if err == nil && !info.ModTime().Before(activeAfter) {
			return true
		}
	}

	statusPath := filepath.Join(workspaceDir, "status.json")
	info, err := os.Stat(statusPath)
	if err != nil || info.ModTime().Before(activeAfter) {
		return false
	}
	data, err := os.ReadFile(statusPath)
	if err != nil {
		return false
	}
	var status struct {
		Active  bool   `json:"active"`
		Running bool   `json:"running"`
		State   string `json:"state"`
		Status  string `json:"status"`
	}
	if json.Unmarshal(data, &status) != nil {
		return false
	}
	state := strings.ToLower(strings.TrimSpace(status.State))
	statusValue := strings.ToLower(strings.TrimSpace(status.Status))
	return status.Active || status.Running || state == "active" || state == "running" || statusValue == "active" || statusValue == "running"
}

func maxTime(a, b time.Time) time.Time {
	if b.After(a) {
		return b
	}
	return a
}

// renderRightPanel 渲染右侧面板：Pipeline 卡片（仅检测到任务时）+ Subagents 卡片 + Context 卡片。
// 整体高度被钳制为 totalHeight，防止右侧面板撑高终端布局。
func (m appModel) renderRightPanel(width, totalHeight int) string {
	cardWidth := rightCardWidth(width)
	contentWidth := rightCardContentWidth(width)

	contextContent := m.renderContextCardContent(contentWidth)
	contextCard := rightCardStyle.Width(cardWidth).Render(contextContent)
	ctxH := lipgloss.Height(contextCard)

	cards := []string{}
	if m.pipelineState.detected {
		reservedSubagentsHeight := rightCardVerticalFrame + 1
		maxPipelineContentHeight := maxInt(1, totalHeight-ctxH-reservedSubagentsHeight-rightCardVerticalFrame)
		pipelineContentHeight := minInt(pipelineCardMaxContentHeight, maxPipelineContentHeight)
		pipelineContent := m.renderPipelineContent(contentWidth, pipelineContentHeight)
		pipelineCard := rightCardStyle.Width(cardWidth).Height(pipelineContentHeight).Render(pipelineContent)
		cards = append(cards, pipelineCard)

		subagentsContentHeight := maxInt(1, totalHeight-lipgloss.Height(pipelineCard)-ctxH-rightCardVerticalFrame)
		subagentsContent := m.renderSubagentsCardContentHeight(contentWidth, subagentsContentHeight)
		subagentsCard := rightCardStyle.Width(cardWidth).Height(subagentsContentHeight).Render(subagentsContent)
		cards = append(cards, subagentsCard)
	} else {
		subagentsContentHeight := maxInt(1, totalHeight-ctxH-rightCardVerticalFrame)
		subagentsContent := m.renderSubagentsCardContentHeight(contentWidth, subagentsContentHeight)
		cards = append(cards, rightCardStyle.Width(cardWidth).Height(subagentsContentHeight).Render(subagentsContent))
	}
	cards = append(cards, contextCard)

	joined := lipgloss.JoinVertical(lipgloss.Left, cards...)
	// Clamp the right panel to totalHeight so it never exceeds the terminal height.
	return lipgloss.NewStyle().
		Width(width).
		Height(totalHeight).
		MaxHeight(totalHeight).
		Render(joined)
}

// renderContextCard 返回 Context 卡片（用于测试）。
func (m appModel) renderContextCard(width int) string {
	cardWidth := rightCardWidth(width)
	contentWidth := rightCardContentWidth(width)
	return rightCardStyle.Width(cardWidth).Render(m.renderContextCardContent(contentWidth))
}

func rightCardWidth(totalWidth int) int {
	return maxInt(4, totalWidth-rightCardBorderFrame)
}

func rightCardContentWidth(totalWidth int) int {
	return maxInt(1, rightCardWidth(totalWidth)-rightCardHorizontalPadding)
}

// renderSubagentsCardContent 渲染 Subagents 内容（Task 4 实现）。
func (m appModel) renderSubagentsCardContent(width int) string {
	return m.renderSubagentsCardContentHeight(width, 0)
}

func (m appModel) renderSubagentsCardContentHeight(width, height int) string {
	hdrStyle := lipgloss.NewStyle().Foreground(lipgloss.Color("250")).Bold(true)
	mutedStyle := lipgloss.NewStyle().Foreground(lipgloss.Color("246"))
	hdr := renderSidebarRow(width, "subagents", "", hdrStyle, mutedStyle)
	maxLines := height

	if m.subagents == nil {
		if maxLines == 1 {
			return hdr
		}
		return hdr + "\n" + mutedStyle.Italic(true).Render(padDisplayWidth("none", width))
	}
	tasks := m.subagentTasks()
	if len(tasks) == 0 {
		if maxLines == 1 {
			return hdr
		}
		empty := mutedStyle.Italic(true).Render(padDisplayWidth("none", width))
		return hdr + "\n" + empty
	}

	dotRunStyle := lipgloss.NewStyle().Foreground(lipgloss.Color("84"))
	dotDoneStyle := lipgloss.NewStyle().Foreground(lipgloss.Color("245"))
	dotFailStyle := lipgloss.NewStyle().Foreground(lipgloss.Color("203"))
	dotStopStyle := lipgloss.NewStyle().Foreground(lipgloss.Color("214"))

	availableTaskRows := len(tasks)
	moreCount := 0
	if maxLines > 0 {
		availableTaskRows = maxInt(0, maxLines-1)
		if len(tasks) > availableTaskRows {
			if availableTaskRows <= 1 {
				moreCount = len(tasks)
				availableTaskRows = 0
			} else {
				availableTaskRows--
				moreCount = len(tasks) - availableTaskRows
			}
		}
	}

	lines := []string{hdr}
	for _, t := range tasks[:minInt(len(tasks), availableTaskRows)] {
		var dot, status string
		dotStyle := dotDoneStyle
		lineStyle := lipgloss.NewStyle().Foreground(lipgloss.Color("248"))
		noDot := false
		switch t.Status {
		case subagent.TaskRunning:
			noDot = true
			status = formatElapsedTime(time.Since(t.StartedAt))
			dotStyle = dotRunStyle
			lineStyle = lipgloss.NewStyle().Foreground(lipgloss.Color("84"))
		case subagent.TaskFailed:
			dot = "✗"
			status = "failed"
			dotStyle = dotFailStyle
			lineStyle = lipgloss.NewStyle().Foreground(lipgloss.Color("203"))
		case subagent.TaskStopped:
			dot = "■"
			status = "stopped"
			dotStyle = dotStopStyle
			lineStyle = lipgloss.NewStyle().Foreground(lipgloss.Color("214"))
		default:
			dot = "✓"
			status = "done"
		}
		nameStyle := lineStyle
		if color := strings.TrimSpace(t.Color); color != "" {
			nameStyle = lipgloss.NewStyle().Foreground(lipgloss.Color(color))
		}
		if noDot {
			lines = append(lines, renderSidebarRow(width, taskDisplayName(t), status, nameStyle, lineStyle))
		} else {
			lines = append(lines, renderSubagentSidebarRow(width, dot, taskDisplayName(t), status, dotStyle, nameStyle, lineStyle))
		}
	}
	if moreCount > 0 {
		lines = append(lines, renderSidebarRow(width, fmt.Sprintf("+%d more", moreCount), "", mutedStyle, mutedStyle))
	}
	return strings.Join(lines, "\n")
}

// renderPipelineOrTasksContent 保留给测试和旧调用点：无 pipeline 时返回空内容。
func (m appModel) renderPipelineOrTasksContent(width, height int) string {
	if m.pipelineState.detected {
		return m.renderPipelineContent(width, height)
	}
	return ""
}

func (m appModel) renderPipelineContent(width, height int) string {
	return m.renderPipelineWindowedContent(width, height)
}

// renderPipelineWindowedContent 渲染满宽 Pipeline 仪表盘：摘要、阶段进度条和 timeline。
func (m appModel) renderPipelineWindowedContent(width, height int) string {
	ps := m.pipelineState

	currentIdx := ps.activeIdx
	if currentIdx < 0 {
		currentIdx = maxInt(0, ps.doneCount-1)
	}
	currentName := ""
	if currentIdx >= 0 && currentIdx < len(ps.phases) {
		currentName = ps.phases[currentIdx].name
	}
	if currentName == "" {
		currentName = "idle"
	}

	titleRight := currentName
	if ps.globalIter > 0 {
		titleRight = fmt.Sprintf("%s ×%d", titleRight, ps.globalIter)
	}

	pendingCount := 0
	retryCount := 0
	activeCount := 0
	for _, ph := range ps.phases {
		switch ph.status {
		case phaseStatusActive:
			activeCount++
		case phaseStatusRetry:
			retryCount++
		case phaseStatusPending:
			pendingCount++
		}
	}

	total := len(ps.phases)
	percent := 0
	if total > 0 {
		percent = int(float64(ps.doneCount) / float64(total) * 100)
	}

	lines := []string{
		renderSidebarRow(width, "pipeline", titleRight, lipgloss.NewStyle().Foreground(lipgloss.Color("250")).Bold(true), lipgloss.NewStyle().Foreground(lipgloss.Color("75")).Bold(true)),
		renderSidebarRow(width, fmt.Sprintf("%d/%d complete", ps.doneCount, total), fmt.Sprintf("%d%%", percent), lipgloss.NewStyle().Foreground(lipgloss.Color("246")), lipgloss.NewStyle().Foreground(lipgloss.Color("246"))),
		renderPipelineProgressBar(ps, width),
		renderSidebarRow(width, fmt.Sprintf("ok %d", ps.doneCount), fmt.Sprintf("now %d", activeCount), lipgloss.NewStyle().Foreground(lipgloss.Color("28")), lipgloss.NewStyle().Foreground(lipgloss.Color("75"))),
		renderSidebarRow(width, fmt.Sprintf("todo %d", pendingCount), fmt.Sprintf("retry %d", retryCount), lipgloss.NewStyle().Foreground(lipgloss.Color("246")), lipgloss.NewStyle().Foreground(lipgloss.Color("214"))),
		renderSidebarRow(width, "timeline", "near", lipgloss.NewStyle().Foreground(lipgloss.Color("250")).Bold(true), lipgloss.NewStyle().Foreground(lipgloss.Color("246"))),
	}

	stageRows := minInt(pipelineMaxStageRows, maxInt(0, height-len(lines)))
	for _, idx := range visiblePipelineStageIndices(ps, stageRows) {
		lines = append(lines, renderPipelineStageLine(ps.phases[idx], idx, currentIdx, width))
	}
	return strings.Join(lines, "\n")
}

func renderPipelineProgressBar(ps pipelineState, width int) string {
	width = maxInt(1, width)
	total := len(ps.phases)
	if total == 0 {
		return strings.Repeat("▱", width)
	}
	parts := make([]string, 0, width)
	for cell := 0; cell < width; cell++ {
		idx := minInt(total-1, cell*total/width)
		status := ps.phases[idx].status
		if status == phaseStatusActive && (cell == 0 || minInt(total-1, (cell-1)*total/width) != idx) {
			parts = append(parts, lipgloss.NewStyle().Foreground(lipgloss.Color("75")).Bold(true).Render("▶"))
			continue
		}
		switch status {
		case phaseStatusDone:
			parts = append(parts, lipgloss.NewStyle().Foreground(lipgloss.Color("28")).Render("▰"))
		case phaseStatusActive:
			parts = append(parts, lipgloss.NewStyle().Foreground(lipgloss.Color("75")).Render("▰"))
		case phaseStatusRetry:
			parts = append(parts, lipgloss.NewStyle().Foreground(lipgloss.Color("214")).Render("▱"))
		default:
			parts = append(parts, lipgloss.NewStyle().Foreground(lipgloss.Color("245")).Render("▱"))
		}
	}
	return strings.Join(parts, "")
}

func visiblePipelineStageIndices(ps pipelineState, available int) []int {
	total := len(ps.phases)
	if available <= 0 {
		return nil
	}
	if available >= total {
		indices := make([]int, total)
		for i := range indices {
			indices[i] = i
		}
		return indices
	}
	center := ps.activeIdx
	if center < 0 {
		center = maxInt(0, ps.doneCount-1)
	}
	start := center - available/2
	start = maxInt(0, minInt(start, total-available))
	indices := make([]int, available)
	for i := range indices {
		indices[i] = start + i
	}
	return indices
}

func renderPipelineStageLine(ph pipelinePhaseEntry, idx, currentIdx, width int) string {
	symbol, status := pipelineStageGlyphAndStatus(ph.status)
	name := ph.name
	if ph.iteration > 0 {
		name = fmt.Sprintf("%s ×%d", name, ph.iteration)
	}
	left := symbol + " " + name
	if idx == currentIdx {
		contentWidth := maxInt(1, width-1)
		content := renderSidebarRow(contentWidth, left, status, lipgloss.NewStyle().Foreground(lipgloss.Color("252")).Bold(true), lipgloss.NewStyle().Foreground(lipgloss.Color("252")))
		return lipgloss.NewStyle().Foreground(lipgloss.Color("68")).Render("▐") +
			lipgloss.NewStyle().Width(contentWidth).Background(lipgloss.Color("234")).Render(content)
	}
	var fg lipgloss.Color
	switch ph.status {
	case phaseStatusDone:
		fg = lipgloss.Color("248")
	case phaseStatusRetry:
		fg = lipgloss.Color("214")
	case phaseStatusActive:
		fg = lipgloss.Color("252")
	default:
		fg = lipgloss.Color("245")
	}
	style := lipgloss.NewStyle().Foreground(fg)
	return renderSidebarRow(width, left, status, style, style)
}

func pipelineStageGlyphAndStatus(status pipelinePhaseStatus) (string, string) {
	switch status {
	case phaseStatusDone:
		return "✓", "done"
	case phaseStatusActive:
		return "▶", "now"
	case phaseStatusRetry:
		return "↻", "retry"
	default:
		return "·", "pending"
	}
}

func renderSidebarRow(width int, left, right string, leftStyle, rightStyle lipgloss.Style) string {
	width = maxInt(1, width)
	if width <= 2 || strings.TrimSpace(right) == "" {
		return leftStyle.Render(padDisplayWidth(truncateDisplayWidth(left, width), width))
	}
	right = truncateDisplayWidth(right, maxInt(1, width/2))
	rightWidth := lipgloss.Width(right)
	leftMax := maxInt(1, width-rightWidth-1)
	left = truncateDisplayWidth(left, leftMax)
	gap := maxInt(0, width-lipgloss.Width(left)-rightWidth)
	return leftStyle.Render(left) + strings.Repeat(" ", gap) + rightStyle.Render(right)
}

func renderSubagentSidebarRow(width int, dot, name, right string, dotStyle, nameStyle, rightStyle lipgloss.Style) string {
	width = maxInt(1, width)
	right = strings.TrimSpace(right)
	if width <= 2 || right == "" {
		return renderSubagentSidebarLeft(width, dot, name, dotStyle, nameStyle)
	}
	right = truncateDisplayWidth(right, maxInt(1, width/2))
	rightWidth := lipgloss.Width(right)
	leftMax := maxInt(1, width-rightWidth-1)
	left := renderSubagentSidebarLeft(leftMax, dot, name, dotStyle, nameStyle)
	gap := maxInt(0, width-lipgloss.Width(left)-rightWidth)
	return left + strings.Repeat(" ", gap) + rightStyle.Render(right)
}

func renderSubagentSidebarLeft(width int, dot, name string, dotStyle, nameStyle lipgloss.Style) string {
	width = maxInt(1, width)
	dot = truncateDisplayWidth(dot, width)
	dotWidth := lipgloss.Width(dot)
	if width <= dotWidth+1 {
		return dotStyle.Render(padDisplayWidth(dot, width))
	}
	nameWidth := maxInt(1, width-dotWidth-1)
	name = truncateDisplayWidth(name, nameWidth)
	left := dotStyle.Render(dot) + " " + nameStyle.Render(name)
	if lipgloss.Width(left) >= width {
		return left
	}
	return left + strings.Repeat(" ", width-lipgloss.Width(left))
}

func padDisplayWidth(text string, width int) string {
	if lipgloss.Width(text) >= width {
		return text
	}
	return text + strings.Repeat(" ", width-lipgloss.Width(text))
}

func formatElapsedTime(d time.Duration) string {
	s := int(d.Seconds())
	if s < 0 {
		s = 0
	}
	if s < 60 {
		return fmt.Sprintf("%ds", s)
	}
	h := s / 3600
	m := (s % 3600) / 60
	sec := s % 60
	if h > 0 {
		return fmt.Sprintf("%dh %dm %ds", h, m, sec)
	}
	return fmt.Sprintf("%dm %ds", m, sec)
}

